        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with arc-sprayed cylinder bores (LDS). This specific B48 variant is de-stroked to 1.6 Liters to bypass heavy displacement taxes in certain global markets, but retains the incredibly strong, closed-deck architecture of the 2.0L version.", crankshaft: "Forged Steel, supported by 5 main bearings. Features twin balance shafts to eliminate 4-cylinder vibrations.", pistonSpeed: "14.5 m/s @ 6000 RPM.", alternator: "150A Valeo (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with an 11.0:1 high-compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M8.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for an 11.0:1 compression ratio.", intakePortFlow: "16-valve DOHC design. Features Valvetronic variable valve lift, eliminating the traditional throttle butterfly (used only as a backup), improving throttle response and fuel economy.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.5 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable. Controlled by Dual VANOS and Valvetronic.", lifterType: "Hydraulic Tappets with intermediate levers.", specialFeature: "Air-to-Water Intercooler. The intake manifold integrates a water-cooled charge air cooler, drastically reducing intake tract length for instant throttle response and incredibly stable intake temperatures." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven map-controlled variable displacement pump.", thermostatOpening: "105°C Electronic map-controlled (Heat Management Module actively drops target temps under heavy load).", oilCooler: "Coolant-to-oil heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Bosch High-Pressure Direct Injection.", maxPressure: "250 Bar (High Pressure Rail).", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm (Transmission limits).", maxSafePowerStock: "240 hp (Restricted by 1.6L displacement and turbo size).", maxSafeRPM: "6500 RPM (Governed by ECU).", weakestLink: "Locked DME, Plastic Charge Pipe, Heat Management Module (Coolant Leaks), 1.6L Displacement Limit." }, electrical: { coils: "Individual Coil Pack system (Coil-on-Plug) pencil-style coils.", ecu: "Bosch MG1 (Heavily Encrypted)." } },
        recommendedParts: { description: "Crucial maintenance parts to keep the highly reliable B48 engine running perfectly.", parts: [ { category: "Aluminum Charge Pipe", brand: "VRSF / FTP Motorsport", note: "MANDATORY UPGRADE: Replaces the explosive plastic factory pipe." }, { category: "Oil Filter Housing Assembly", brand: "Genuine BMW", note: "Replace the entire plastic housing if leaking; changing just the gasket often fails." }, { category: "Valve Cover Assembly", brand: "Genuine BMW", note: "Includes integrated PCV valve. Replace whole cover if whistling." }, { category: "Heat Management Module", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Contains rotary valve. Replace proactively to stop overheating." }, { category: "Spark Plugs", brand: "NGK Laser Iridium", note: "Specific multi-ground plugs for direct injection. Gap tightly if tuned." }, { category: "Ignition Coil Pack", brand: "Bosch / Eldor", note: "Replace all 4 proactively; they fail under tuned boost." }, { category: "Coolant Expansion Tank", brand: "Behr / Genuine BMW", note: "The factory tanks split down the seam. Replace proactively." }, { category: "Water Pump", brand: "Saleri / Hepu", note: "Mechanical pump on the B48. Replace if weeping." } ] },
