          fluidsAndDrivetrain: [ { interval: "40,000 km", timeLimit: "4 years", task: "Transfer Case Fluid (xDrive)", details: "Extract and refill the xDrive transfer case.", parts: ["0.5L DTF 1"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Rear Differential Oil", details: "Extract and refill the rear differential.", parts: ["0.8L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 Low Viscosity fluid.", parts: ["1.0L DOT 4 LV"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Automatic Transmission Fluid (ZF 8HP)", details: "Drain and refill the ZF 8HP automatic transmission fluid and replace the integrated pan/filter. Ignore BMW's 'lifetime' fluid claim.", parts: ["ZF Lifeguard 8", "Filter Pan"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" } ],
          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 0W-20 or 5W-30 Synthetic. The timing chain tensioner and turbocharger bearings demand clean oil.", parts: ["5.25L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the pollen filter under the cowl.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "35 EUR" } ],
          ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Charge Pipe Upgrade", details: "CRITICAL: Replace the factory plastic charge pipe with an aluminum one. It will blow up under stock or tuned boost.", parts: ["Aluminum Charge Pipe"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "180 EUR" }, { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace specific B48 spark plugs. Tuned engines require gap adjustment and more frequent intervals.", parts: ["4x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "Unlimited", task: "Ignition Coil Replacement", details: "Proactively replace all pencil coils. They fail constantly under the extreme heat of direct injection and boost.", parts: ["4x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Cover Assembly", details: "Replace the entire valve cover to stop oil leaking onto the exhaust and cure the integrated PCV whistling issues causing massive vacuum leaks.", parts: ["Valve Cover Assy"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Assembly", details: "The plastic OFH can warp and leak. Replace the entire unit if weeping coolant or oil is detected.", parts: ["Oil Filter Housing"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "8 years", task: "Tension Strut Bushings", details: "Replace the fluid-filled front control arm bushings with solid rubber to cure steering shimmy under braking.", parts: ["Lemförder Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "100,000 km", timeLimit: "10 years", task: "Rear Shock Mounts", details: "Replace the rear shock mounts; they cause clunking over bumps.", parts: ["Meyle HD RSMs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "80,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "Replace the accessory drive belt and the tensioner pulley.", parts: ["Continental Belt Kit"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" } ],
          coolingAndHvac: [ { interval: "40,000 km", timeLimit: "3 years", task: "Coolant Flush", details: "Drain and refill the aluminum block with specified HT-12 coolant.", parts: ["7.0L HT-12 Coolant"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Water Pump & Heat Management Module", details: "Replace the mechanical water pump and heat management module proactively.", parts: ["Water Pump", "Heat Mgmt Module"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "Unlimited", task: "Coolant Expansion Tank & Flanges", details: "Replace the incredibly fragile plastic expansion tank and the plastic coolant flanges connecting to the cylinder head before they snap.", parts: ["Expansion Tank", "Coolant Flange"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" } ],
          engineMechanical: [ { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Valve Cleaning (Walnut Blasting)", details: "Because it is direct-injected, fuel never washes the intake valves. Carbon buildup will severely choke the engine and cause misfires. Requires professional walnut blasting.", parts: ["Intake Gaskets", "Blasting Labor"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "350 EUR" }, { interval: "120,000 km", timeLimit: "Unlimited", task: "Turbocharger Wastegate Inspection", details: "Inspect the turbo wastegate linkage for excessive play. If it rattles loudly and fails to hold boost, the turbo requires a rebuild.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "0 EUR" } ]
